const now = new Date();
const hour = now.getUTCHours();
const day = now.getUTCDay();

// No trading on weekends
if (day === 0 || day === 6) {
  throw new Error('Weekend - market closed');
}

// London: 08:00-17:00 UTC | New York: 13:00-22:00 UTC
const londonOpen = hour >= 8 && hour < 17;
const nyOpen = hour >= 13 && hour < 22;

if (!londonOpen && !nyOpen) {
  throw new Error(`Outside trading sessions - UTC hour: ${hour}`);
}

const session = (londonOpen && nyOpen) ? 'London+NY Overlap' : londonOpen ? 'London' : 'New York';
return [{ json: { session, utcHour: hour } }];

// ============================================================
// XAU/USD (Gold) Indicator Engine — n8n Code Node
// Input: $input.all()[0].json.values  (Twelve Data time_series array, newest-first)
// Output: single item with all computed fields for the AI prompt
// ============================================================

const candles = $input.all()[0].json.values;

if (!candles || candles.length < 55) {
  throw new Error(`Not enough candles returned (${candles ? candles.length : 0}). Need at least 55 for MACD/EMA50 to stabilize.`);
}

// Twelve Data returns newest-first — reverse to oldest-first for indicator math
const ohlc = candles.slice().reverse().map(c => ({
  time: c.datetime,
  open: parseFloat(c.open),
  high: parseFloat(c.high),
  low: parseFloat(c.low),
  close: parseFloat(c.close)
}));

const closes = ohlc.map(c => c.close);
const highs = ohlc.map(c => c.high);
const lows = ohlc.map(c => c.low);

// ---------- EMA ----------
function ema(values, period) {
  const k = 2 / (period + 1);
  const result = [values[0]];
  for (let i = 1; i < values.length; i++) {
    result.push(values[i] * k + result[i - 1] * (1 - k));
  }
  return result;
}

const ema20Series = ema(closes, 20);
const ema50Series = ema(closes, 50);
const ema20 = ema20Series[ema20Series.length - 1];
const ema50 = ema50Series[ema50Series.length - 1];

// ---------- RSI (14) ----------
function rsi(values, period = 14) {
  let gains = 0, losses = 0;
  for (let i = values.length - period; i < values.length; i++) {
    const diff = values[i] - values[i - 1];
    if (diff >= 0) gains += diff; else losses -= diff;
  }
  const avgGain = gains / period;
  const avgLoss = losses / period;
  if (avgLoss === 0) return 100;
  const rs = avgGain / avgLoss;
  return 100 - 100 / (1 + rs);
}

const rsiValue = rsi(closes, 14);

// ---------- ATR (14) ----------
function atr(ohlcData, period = 14) {
  const trs = [];
  for (let i = 1; i < ohlcData.length; i++) {
    const high = ohlcData[i].high;
    const low = ohlcData[i].low;
    const prevClose = ohlcData[i - 1].close;
    const tr = Math.max(
      high - low,
      Math.abs(high - prevClose),
      Math.abs(low - prevClose)
    );
    trs.push(tr);
  }
  const recent = trs.slice(-period);
  return recent.reduce((a, b) => a + b, 0) / recent.length;
}

const atrValue = atr(ohlc, 14);

// Average ATR over a longer lookback, used to judge if current volatility is "alive"
function averageAtrSeries(ohlcData, period = 14, lookback = 30) {
  const trs = [];
  for (let i = 1; i < ohlcData.length; i++) {
    const high = ohlcData[i].high;
    const low = ohlcData[i].low;
    const prevClose = ohlcData[i - 1].close;
    trs.push(Math.max(high - low, Math.abs(high - prevClose), Math.abs(low - prevClose)));
  }
  const atrSeries = [];
  for (let i = period; i <= trs.length; i++) {
    const slice = trs.slice(i - period, i);
    atrSeries.push(slice.reduce((a, b) => a + b, 0) / period);
  }
  return atrSeries.slice(-lookback);
}

const atrHistory = averageAtrSeries(ohlc, 14, 30);
const avgAtr30 = atrHistory.reduce((a, b) => a + b, 0) / atrHistory.length;

// ---------- MACD (12, 26, 9) ----------
const ema12Series = ema(closes, 12);
const ema26Series = ema(closes, 26);
const macdLineSeries = ema12Series.map((v, i) => v - ema26Series[i]);
const macdSignalSeries = ema(macdLineSeries, 9);
const macdHistogramSeries = macdLineSeries.map((v, i) => v - macdSignalSeries[i]);

const macdLine = macdLineSeries[macdLineSeries.length - 1];
const macdSignal = macdSignalSeries[macdSignalSeries.length - 1];
const macdHistogram = macdHistogramSeries[macdHistogramSeries.length - 1];
const prevMacdLine = macdLineSeries[macdLineSeries.length - 2];
const prevMacdSignal = macdSignalSeries[macdSignalSeries.length - 2];

const macdBullishCross = prevMacdLine <= prevMacdSignal && macdLine > macdSignal;
const macdBearishCross = prevMacdLine >= prevMacdSignal && macdLine < macdSignal;

// ---------- Trend ----------
const trend = ema20 > ema50 ? "BULLISH" : "BEARISH";
const candidateDirection = trend === "BULLISH" ? "BUY" : "SELL";

// ---------- Candlestick pattern (last closed candle) ----------
function detectPattern(c, prev) {
  const body = Math.abs(c.close - c.open);
  const range = c.high - c.low;
  if (range === 0) return "NONE";
  const upperWick = c.high - Math.max(c.open, c.close);
  const lowerWick = Math.min(c.open, c.close) - c.low;
  const bullish = c.close > c.open;

  // Marubozu: body fills almost the whole range, negligible wicks
  if (body / range > 0.9) {
    return bullish ? "BULLISH_MARUBOZU" : "BEARISH_MARUBOZU";
  }
  // Hammer: small body, long lower wick, little upper wick, near top of range
  if (lowerWick > body * 2 && upperWick < body * 0.5) {
    return "HAMMER";
  }
  // Shooting star: small body, long upper wick, little lower wick
  if (upperWick > body * 2 && lowerWick < body * 0.5) {
    return "SHOOTING_STAR";
  }
  // Engulfing: current body fully engulfs previous body, opposite direction
  if (prev) {
    const prevBullish = prev.close > prev.open;
    if (bullish && !prevBullish && c.close > prev.open && c.open < prev.close) {
      return "BULLISH_ENGULFING";
    }
    if (!bullish && prevBullish && c.close < prev.open && c.open > prev.close) {
      return "BEARISH_ENGULFING";
    }
  }
  return "NONE";
}

const lastCandle = ohlc[ohlc.length - 1];
const prevCandle = ohlc[ohlc.length - 2];
const pattern = detectPattern(lastCandle, prevCandle);

// ---------- Pullback check ----------
// "Pulled back toward EMA" = recent close came within ~0.4x ATR of EMA20
// before the current push away from it (avoids chasing extended moves)
function hasPullback(ohlcData, ema20Series, atrValue, direction, lookback = 5) {
  const recentCloses = ohlcData.slice(-lookback).map(c => c.close);
  const recentEma20 = ema20Series.slice(-lookback);
  for (let i = 0; i < recentCloses.length; i++) {
    const distance = Math.abs(recentCloses[i] - recentEma20[i]);
    if (distance <= atrValue * 0.4) return true;
  }
  return false;
}

const pullback = hasPullback(ohlc, ema20Series, atrValue, candidateDirection, 5);

// ---------- Volatility check ----------
// Gold needs meaningful ATR to be worth trading 15m. If current ATR is well
// below its own 30-period average, the market is "dead" — skip.
const volatilityOk = atrValue >= avgAtr30 * 0.6;

// ---------- Spread check ----------
// Twelve Data's free/basic time_series endpoint does not return live bid/ask.
// Set this from your broker/execution feed if available. As a placeholder,
// this assumes spread is acceptable if ATR is healthy (proxy only — replace
// with a real bid/ask check from your execution server before going live).
const currentSpread = $input.all()[0].json.currentSpread || null; // wire this in from your broker feed if you have it
const maxAcceptableSpread = atrValue * 0.1; // e.g. spread shouldn't exceed 10% of ATR
const spreadOk = currentSpread !== null ? currentSpread <= maxAcceptableSpread : true; // true = unverified, not "confirmed OK"

// ---------- News blackout ----------
// Placeholder stub — wire this to an economic calendar API (e.g. ForexFactory,
// FRED release calendar, or a paid calendar API) and replace `false` with a
// real check against high-impact USD events (CPI, NFP, FOMC) within ±30 min.
const newsBlackout = false; // TODO: replace with real calendar lookup

// ---------- Price & SL/TP (gold-tuned ATR multipliers) ----------
const currentPrice = closes[closes.length - 1];

// Gold's ATR is naturally larger in $ terms than EUR/USD's pip-based ATR.
// Keeping the same 2:1 R:R structure, but multipliers can be tuned after
// backtesting — these are reasonable starting points for XAU/USD 15m.
const slMultiplier = 1.5;
const tpMultiplier = 3.0;

let sl, tp;
if (candidateDirection === "BUY") {
  sl = round2(currentPrice - atrValue * slMultiplier);
  tp = round2(currentPrice + atrValue * tpMultiplier);
} else {
  sl = round2(currentPrice + atrValue * slMultiplier);
  tp = round2(currentPrice - atrValue * tpMultiplier);
}

function round2(n) {
  return Math.round(n * 100) / 100;
}

// ---------- Confluence score (0-4) — computed here, not by the LLM ----------
let confluenceScore = 0;
const reasons = [];

// +1: RSI in neutral zone (35-65) — valid entry momentum, not extended
if (rsiValue >= 35 && rsiValue <= 65) {
  confluenceScore += 1;
  reasons.push(`RSI ${rsiValue.toFixed(1)} neutral`);
}

// +1: MACD alignment with trend direction (line vs signal AND histogram sign)
// counted as ONE signal since histogram sign is derived from line-vs-signal
const macdAligned = candidateDirection === "BUY" ? macdLine > macdSignal : macdLine < macdSignal;
if (macdAligned) {
  confluenceScore += 1;
  reasons.push(`MACD aligned (${macdBullishCross ? "fresh bull cross" : macdBearishCross ? "fresh bear cross" : "holding"})`);
}

// +1: Candlestick pattern matches direction
const buyPatterns = ["HAMMER", "BULLISH_ENGULFING", "BULLISH_MARUBOZU"];
const sellPatterns = ["SHOOTING_STAR", "BEARISH_ENGULFING", "BEARISH_MARUBOZU"];
if ((candidateDirection === "BUY" && buyPatterns.includes(pattern)) ||
    (candidateDirection === "SELL" && sellPatterns.includes(pattern))) {
  confluenceScore += 1;
  reasons.push(`Pattern ${pattern}`);
}

// +1: Volatility is healthy relative to its own average (genuine trending conditions)
if (atrValue > avgAtr30) {
  confluenceScore += 1;
  reasons.push("ATR above 30-period average");
}

// ---------- Final output ----------
return [{
  json: {
    symbol: "XAU/USD",
    price: round2(currentPrice),
    ema20: round2(ema20),
    ema50: round2(ema50),
    trend,
    rsi: Math.round(rsiValue * 10) / 10,
    atr: round2(atrValue),
    avgAtr30: round2(avgAtr30),
    macdLine: Math.round(macdLine * 1000) / 1000,
    macdSignal: Math.round(macdSignal * 1000) / 1000,
    macdHistogram: Math.round(macdHistogram * 1000) / 1000,
    macdBullishCross,
    macdBearishCross,
    pattern,
    confluenceScore,
    confluenceReasons: reasons,
    hasPullback: pullback,
    volatilityOk,
    spreadOk,
    newsBlackout,
    sl,
    tp
  }
}];

// ── Robust JSON extractor ──
// Handles: .output string, nested text blocks, direct JSON, markdown fences
const item = $input.first().json;

let raw = '';

// Try common output shapes from LangChain agent
if (typeof item.output === 'string') {
  raw = item.output;
} else if (item.output && typeof item.output === 'object') {
  raw = JSON.stringify(item.output);
} else if (typeof item.text === 'string') {
  raw = item.text;
} else if (Array.isArray(item.content)) {
  raw = item.content
    .filter(b => b.type === 'text')
    .map(b => b.text)
    .join('');
} else {
  raw = JSON.stringify(item);
}

// Strip markdown fences and whitespace
const clean = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// Extract the first JSON object found
const jsonMatch = clean.match(/\{[\s\S]*?\}/);
if (!jsonMatch) {
  throw new Error(`AI response has no JSON object. Raw: ${raw.substring(0, 200)}`);
}

let decision;
try {
  decision = JSON.parse(jsonMatch[0]);
} catch (e) {
  throw new Error(`JSON parse failed: ${e.message}. Raw: ${jsonMatch[0].substring(0, 200)}`);
}

// Validate required fields
if (!decision.action || !['BUY', 'SELL', 'SKIP'].includes(decision.action.toUpperCase())) {
  throw new Error(`Invalid action in AI response: ${decision.action}`);
}
decision.action = decision.action.toUpperCase();

const indicators = $('Indicator Engine').first().json;

return [{
  json: {
    action: decision.action,
    confidence: Number(decision.confidence) || 0,
    sl: parseFloat(decision.sl) || parseFloat(indicators.sl),
    tp: parseFloat(decision.tp) || parseFloat(indicators.tp),
    reason: decision.reason || 'No reason provided',
    symbol: indicators.symbol,
    price: parseFloat(indicators.price),
    atr: parseFloat(indicators.atr),
    trend: indicators.trend,
    rsi: parseFloat(indicators.rsi),
    macdBullishCross: indicators.macdBullishCross,
    macdBearishCross: indicators.macdBearishCross,
    macdHistogram: parseFloat(indicators.macdHistogram),
    pattern: indicators.pattern,
    momentumBias: indicators.momentumBias
  }
}];

