const d = $input.first().json;
const reasons = [];

// ─────────────────────────────────────────
// FIX 1: MAX DAILY TRADES LIMIT
// ─────────────────────────────────────────
const today = new Date().toISOString().slice(0, 10);
const workflowStaticData = $getWorkflowStaticData('global');
if (!workflowStaticData.tradeDates) workflowStaticData.tradeDates = {};
if (!workflowStaticData.tradeDates[today]) workflowStaticData.tradeDates[today] = 0;
//const MAX_DAILY_TRADES = 4;
const todayCount = workflowStaticData.tradeDates[today];
//if (todayCount >= MAX_DAILY_TRADES) {
//  reasons.push(`Daily trade limit reached: ${todayCount}/${MAX_DAILY_TRADES}`);
//}

// ─────────────────────────────────────────
// FIX 2: CONSECUTIVE LOSS CIRCUIT BREAKER
// NOTE: consecutiveLosses/lastLossDirection are only meaningful if you have
// a downstream node that updates them when a trade actually closes (checking
// your execution server for win/loss and calling
// workflowStaticData.consecutiveLosses++ / = 0 accordingly). Without that
// node, this check is currently a no-op — it will never block anything.
// ─────────────────────────────────────────
const MAX_CONSECUTIVE_LOSSES = 3;
if (!workflowStaticData.consecutiveLosses) workflowStaticData.consecutiveLosses = 0;
if (!workflowStaticData.lastLossDirection) workflowStaticData.lastLossDirection = null;
if (
  workflowStaticData.consecutiveLosses >= MAX_CONSECUTIVE_LOSSES &&
  workflowStaticData.lastLossDirection === d.action
) {
  reasons.push(`Circuit breaker: ${workflowStaticData.consecutiveLosses} consecutive ${d.action} losses — paused for this direction`);
}

// ─────────────────────────────────────────
// SIGNAL CHECKS
// ─────────────────────────────────────────
if (d.action === 'SKIP') reasons.push('AI said SKIP');
if (d.confidence < 70) reasons.push(`Low confidence: ${d.confidence}%`);

// Defense-in-depth: re-check upstream conditions here even though the AI
// prompt should already SKIP on these. Only block if the field is explicitly
// present and false/true — avoids false blocks if a field didn't propagate.
if (d.volatilityOk === false) reasons.push('Volatility check failed upstream');
if (d.spreadOk === false) reasons.push('Spread check failed upstream');
if (d.newsBlackout === true) reasons.push('Within news blackout window');

// ─────────────────────────────────────────
// SL/TP SANITY CHECKS
// ─────────────────────────────────────────
if (d.action === 'BUY'  && d.sl >= d.price) reasons.push('SL above price for BUY');
if (d.action === 'SELL' && d.sl <= d.price) reasons.push('SL below price for SELL');

const slDist = Math.abs(d.price - d.sl);
const tpDist = Math.abs(d.tp - d.price);

if (slDist === 0) reasons.push('SL distance is zero');
if (tpDist === 0) reasons.push('TP distance is zero');

// Round before comparing — raw float division (e.g. 1.9999999999) can land
// just under a clean threshold like 2.0 due to floating-point rounding on
// the SL/TP inputs, wrongly blocking trades that are actually exactly at minimum.
const rr = slDist > 0 ? Math.round((tpDist / slDist) * 100) / 100 : 0;
const MIN_RR = 2.0;
if (rr < MIN_RR) reasons.push(`R:R ${rr.toFixed(2)} below minimum ${MIN_RR}`);

// ─────────────────────────────────────────
// LOT SIZE CALCULATION (1% risk) — GOLD CONTRACT MATH
//
// Gold is priced in $ per troy ounce, not pips. A standard XAU/USD CFD
// "lot" is typically 100 oz, meaning a $1 price move = $100 P&L per lot.
// CONFIRM THIS WITH YOUR BROKER — contract size varies (some brokers use
// 100 oz/lot, others 10 oz "mini lots", or 1 oz "micro lots"). Set
// CONTRACT_SIZE to match your actual broker spec before going live.
// ─────────────────────────────────────────
const accountBalance = 10000;
const riskAmount = accountBalance * 0.01; // $100 at 1% risk
const CONTRACT_SIZE = 100; // $ P&L per $1 move, per standard lot — VERIFY WITH BROKER

const lots = slDist > 0
  ? parseFloat((riskAmount / (slDist * CONTRACT_SIZE)).toFixed(2))
  : 0.01;

const passed = reasons.length === 0 && (d.action === 'BUY' || d.action === 'SELL');

// Increment daily counter only for trades actually approved here.
// This counts approved signals, not confirmed fills — if your execution
// server can reject/fail an order, consider moving this increment to fire
// only after a confirmed fill instead.
if (passed) {
  workflowStaticData.tradeDates[today] += 1;
}

return [{
  json: {
    ...d,
    lots: Math.max(0.01, Math.min(lots, 0.10)),
    rr: parseFloat(rr.toFixed(2)),
    passed,
    blockReasons: reasons,
    todayTradeCount: workflowStaticData.tradeDates[today],
    consecutiveLosses: workflowStaticData.consecutiveLosses
  }
}];
